#include "Sistema.h"
#include <iostream>
#include <limits>
using namespace std;
static string ler(string p){cout<<p;string s;getline(cin,s);return s;}
static int num(string p){try{return stoi(ler(p));}catch(...){return 0;}}
static void mostrar(Sistema& s,string c){for(auto r:s.lista(c)){for(auto& kv:r)cout<<kv.first<<": "<<kv.second<<" | ";if(c=="livros")cout<<(s.ocupado(stoi(r["codigo"]))?"Emprestado":"Disponivel");cout<<'\n';}}
int main(){try{Sistema s("biblioteca_terminal.txt");while(cin){cout<<"\nBIBLIOTECA DEMO 1.2\n1 Livros  2 Usuarios  3 Cadastrar livro  4 Cadastrar usuario\n5 Emprestar  6 Devolver  7 Emprestimos  8 Historico\n9 Reservar  10 Reservas  11 Cancelar reserva  12 Lembrete simulado\n13 Atrasos  14 Pesquisar livro  0 Sair\n";int op=num("Opcao: ");string e; if(op==0)break;switch(op){case 1:mostrar(s,"livros");break;case 2:mostrar(s,"usuarios");break;case 3:{auto id=num("Codigo: ");auto t=ler("Titulo: "),a=ler("Autor: ");e=s.gravar("livros",{{"codigo",to_string(id)},{"titulo",t},{"autor",a}});break;}case 4:{auto id=num("Codigo: ");auto n=ler("Nome: "),m=ler("Email: "),t=ler("Tipo (Aluno/Professor): ");e=s.gravar("usuarios",{{"codigo",to_string(id)},{"nome",n},{"email",m},{"tipo",t}});break;}case 5:{int l=num("Livro: "),u=num("Usuario: ");e=s.emprestar(l,u,Sistema::hoje());break;}case 6:e=s.devolver(num("Codigo do emprestimo: "),Sistema::hoje());break;case 7:mostrar(s,"emprestimos");break;case 8:mostrar(s,"historico");break;case 9:{int l=num("Livro: "),u=num("Usuario: ");e=s.reservar(l,u);break;}case 10:mostrar(s,"reservas");break;case 11:e=s.cancelarReserva(num("Reserva: "));break;case 12:e=s.lembrar(num("Emprestimo: "));break;case 13:for(auto r:s.lista("emprestimos"))if(r["situacao"]=="Ativo"&&r["prazo"]<Sistema::hoje())cout<<r["codigo"]<<" | "<<s.nome("livros",stoi(r["livro"]))<<" | "<<r["prazo"]<<'\n';break;case 14:{auto r=s.buscar("livros",num("Codigo: "));if(r.empty())e="Nao encontrado";else cout<<r["titulo"]<<" - "<<r["autor"]<<'\n';break;}default:e="Opcao invalida";}if(!e.empty())cout<<e<<'\n';else if(op==3||op==4||op==5||op==6||op==9||op==11||op==12)cout<<"Operacao concluida.\n";}}catch(const exception& e){cerr<<e.what()<<'\n';return 1;}}
